package com.oms.channel.platform;
import com.oms.messaging.*;
import org.springframework.stereotype.Component;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import javax.annotation.Resource;import java.util.*;
import static com.oms.messaging.MessageOutbox.*;
@Component @ConditionalOnProperty(name="oms.messaging.enabled",havingValue="true") public class ProductPullMessage implements MessageHandler {
 @Resource PlatformProductService products;@Resource MessageOutbox outbox;
 public Map<String,Object> context(String c,Map<String,Object> m){Map<String,Object> r=new LinkedHashMap<>();r.put("path","/oms-channel/platformProducts");r.put("channelId",n(products.task(c,n(m,"business_id")),"channel_id"));return r;}
 public List<String> rateKeys(String c,Map<String,Object> m){Map<String,Object> r=products.db.queryForMap("SELECT b.expected_shop_id,a.app_key,a.id app_id,a.simulation_mode,a.company_code FROM channel_product_pull t JOIN channel_platform_binding b ON UPPER(b.company_code)=UPPER(t.company_code) AND b.channel_id=t.channel_id JOIN channel_platform_app a ON a.company_code=b.company_code AND a.id=b.app_id WHERE t.company_code=? AND t.id=?",c,n(m,"business_id"));return PlatformRateIdentity.keys(r);}
 public String type(){return "PRODUCT_PULL";}
 public Outcome handle(String c,Map<String,Object> message){long id=n(message,"business_id");Map<String,Object> before=products.task(c,id);if(n(before,"work_version")!=n(message,"business_version"))return Outcome.done("已有更新的任务版本，原通知结束");String state=s(before,"state");if(state.equals("SUCCESS")){products.matchWake(c,n(before,"channel_id"));return Outcome.done("平台商品拉取已完成；绑定任务独立跟踪");}if(Arrays.asList("FAILED","PARTIAL").contains(state))return Outcome.failed(s(before,"last_error").isEmpty()?"部分商品拉取失败，请查看平台商品任务":s(before,"last_error"));products.process(c,id);Map<String,Object> after=products.task(c,id);state=s(after,"state");if(state.equals("SUCCESS")){products.matchWake(c,n(after,"channel_id"));return Outcome.done("平台商品拉取已完成；绑定任务独立跟踪");}if(Arrays.asList("FAILED","PARTIAL").contains(state))return Outcome.failed(s(after,"last_error").isEmpty()?"部分商品拉取失败，请查看原任务":s(after,"last_error"));return Outcome.again("分页断点已保存，继续下一批商品",5);}
 public void replay(String c,Map<String,Object> message,String actor,String reason){long id=n(message,"business_id");Map<String,Object> task=products.task(c,id);String state=s(task,"state");if(Arrays.asList("FAILED","PARTIAL").contains(state)){products.retry(c,id);return;}require(Arrays.asList("PENDING","RUNNING").contains(state),"原商品任务已完成，不能重复申请");require(n(task,"work_version")==n(message,"business_version"),"原商品任务版本已变化，请查看最新通知");require(s(task,"platform_shop_id").equals(s(products.shop(c,n(task,"channel_id")),"expected_shop_id")),"店铺身份变化，请重新核对原任务");require(products.db.queryForObject("SELECT COUNT(*) FROM channel_product_pull WHERE company_code=? AND id=? AND lease_until>NOW()",Long.class,c,id)==0,"原任务仍在执行，请等待在途处理完成");outbox.enqueue(c,type(),id,n(task,"work_version"),s(message,"business_number"),"RETRY:"+s(message,"event_id")+":"+token(),0);}
}
